        for i in(0..self.muzzles.len()).rev(){self.muzzles[i].life-=dt;if self.muzzles[i].life<=0.0{self.muzzles.swap_remove(i);}}
        for i in(0..self.muzzle_particles.len()).rev(){let p=&mut self.muzzle_particles[i];p.life-=dt;moved(&mut p.position,p.velocity,dt);if p.life<=0.0{self.muzzle_particles.swap_remove(i);}}
