fn alive(b:&Body)->bool{b.ship.as_ref().is_some_and(|s|s.flags&(crate::ship_state::DEAD|crate::ship_state::RETREATED|crate::ship_state::DOCKED)==0&&s.armor.as_ref().is_some_and(|a|a.data[14]>0.0))}
/// Reads the sole bulkhead and Edict authorities; never a mirrored FX timer.
